import React, { useRef } from "react";
import Marker from "./Marker";
import "./Map.css";

function Map({ plants, onMarkerClick, onMapClick, adminAddMode }) {
    const mapRef = useRef();

    const handleMapClick = (e) => {
        if (!onMapClick) return;
        const rect = mapRef.current.getBoundingClientRect();
        const x = ((e.clientX - rect.left) / rect.width) * 100;
        const y = ((e.clientY - rect.top) / rect.height) * 100;
        onMapClick({
            x: Math.round(x * 100) / 100,
            y: Math.round(y * 100) / 100,
        });
    };

    return (
        <div className="map-container" style={{ position: "relative" }}>
            <img
                ref={mapRef}
                src="/map.svg"
                alt="����� ������"
                className="map-img"
                style={{ cursor: adminAddMode ? "crosshair" : "default" }}
                onClick={adminAddMode ? handleMapClick : undefined}
            />
            {plants.map((plant) => (
                <Marker key={plant.id} plant={plant} onClick={onMarkerClick} />
            ))}
        </div>
    );
}

export default Map;
